{
  "scenarios": [
    {
      "id": "posting-positive-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-posting-runs"
      },
      "category": "positive",
      "purpose": "Representar uma transação com identificadores em branco, textos curtos e valor negativo, sem presumir rejeição de transporte por regras de negócio ausentes.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "crossReferences": "",
            "accounts": "",
            "categoryBalances": "",
            "transactionOutput": "",
            "rejectionOutput": ""
          },
          "transactions": [
            {
              "transactionId": "",
              "typeCode": "",
              "categoryCode": 0,
              "source": "",
              "description": "",
              "amount": -0.01,
              "merchantId": 0,
              "merchantName": "",
              "merchantCity": "",
              "merchantZip": "",
              "cardNumber": "",
              "originalTimestamp": "",
              "processingTimestamp": ""
            }
          ]
        }
      },
      "expectedFromContract": {
        "transport": "O corpo satisfaz o schema declarado. Strings curtas são preenchidas à direita com espaços; identificadores em branco e valores negativos representáveis não são excluídos.",
        "on200": {
          "required": [
            "transactionsProcessed",
            "transactionsRejected",
            "postedTransactions",
            "rejections",
            "diagnostics"
          ],
          "obligations": [
            "Ao concluir normalmente o processamento deste único registro, transactionsProcessed é 1.",
            "A ausência da chave na consulta de cartão produz rejeição 0100; a ausência da conta após localizar o cartão produz 0101.",
            "Rejeições preservam a transação de entrada e possuem reasonDescription com 76 caracteres.",
            "Se houver rejeição, o programa atribui returnCode 4.",
            "Se aceita, a transação recebe processingTimestamp baseado em CURRENT-DATE; o valor negativo é somado, ainda negativo, a currentCycleDebit."
          ]
        },
        "on500": "Uma falha fatal detectada usa ExecutionFailure; alterações anteriores não são desfeitas. A entrega do erro depende do ambiente."
      },
      "limitations": [
        "Os bindings vazios são strings permitidas pelo schema, não fixtures nem afirmações de existência de datasets.",
        "Sem datasets provisionados conhecidos, não é possível determinar aceitação, motivo de rejeição ou conclusão HTTP 200.",
        "A categoria positive indica representabilidade do request, não sucesso de execução."
      ]
    },
    {
      "id": "posting-boundary-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-posting-runs"
      },
      "category": "boundary",
      "purpose": "Representar o limite inferior de cardinalidade do arquivo diário: nenhum registro.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "crossReferences": "",
            "accounts": "",
            "categoryBalances": "",
            "transactionOutput": "",
            "rejectionOutput": ""
          },
          "transactions": []
        }
      },
      "expectedFromContract": {
        "transport": "transactions vazio é explicitamente representável.",
        "on200": {
          "required": [
            "transactionsProcessed",
            "transactionsRejected",
            "postedTransactions",
            "rejections",
            "diagnostics"
          ],
          "obligations": [
            "Nenhum registro diário é processado ou rejeitado; ambos os contadores são 0.",
            "O contrato não inicializa explicitamente returnCode para uma execução sem rejeições.",
            "A abertura OUTPUT de TRANFILE e DALYREJS não promete preservar conteúdo anterior."
          ]
        },
        "on500": "Falhas fatais de abertura ou fechamento continuam possíveis e são mapeadas para ExecutionFailure quando detectadas e entregues pelo ambiente."
      },
      "limitations": [
        "Bindings vazios são valores de transporte permitidos, sem garantia de resolução.",
        "Entrada vazia não elimina as precondições de arquivos.",
        "Não são prescritos textos exatos de diagnostics."
      ]
    },
    {
      "id": "posting-negative-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-posting-runs"
      },
      "category": "negative",
      "purpose": "Omitir transactions, propriedade obrigatória do corpo.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "crossReferences": "",
            "accounts": "",
            "categoryBalances": "",
            "transactionOutput": "",
            "rejectionOutput": ""
          }
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligations": [
          "O request não satisfaz required: [bindings, transactions].",
          "A rejeição pertence ao transporte, não aos códigos COBOL de rejeição de transações."
        ],
        "responseSchema": "A resposta 400 não declara schema de corpo."
      },
      "limitations": [
        "Não há mensagem, formato de erro ou diagnóstico obrigatório para HTTP 400.",
        "O cenário não exercita consultas ou alterações de arquivos."
      ]
    },
    {
      "id": "posting-negative-02",
      "operation": {
        "method": "POST",
        "path": "/transaction-posting-runs"
      },
      "category": "negative",
      "purpose": "Fornecer amount com fração não representável em centavos.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "crossReferences": "",
            "accounts": "",
            "categoryBalances": "",
            "transactionOutput": "",
            "rejectionOutput": ""
          },
          "transactions": [
            {
              "transactionId": "",
              "typeCode": "",
              "categoryCode": 0,
              "source": "",
              "description": "",
              "amount": 0.001,
              "merchantId": 0,
              "merchantName": "",
              "merchantCity": "",
              "merchantZip": "",
              "cardNumber": "",
              "originalTimestamp": "",
              "processingTimestamp": ""
            }
          ]
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligations": [
          "amount viola multipleOf: 0.01 do schema Amount.",
          "A rejeição de transporte não é uma rejeição de negócio 0100, 0101, 0102 ou 0103."
        ],
        "responseSchema": "A resposta 400 não declara schema de corpo."
      },
      "limitations": [
        "Não se presume arredondamento ou truncamento de um request que viola o schema.",
        "Não há envelope de erro obrigatório."
      ]
    },
    {
      "id": "interest-positive-01",
      "operation": {
        "method": "POST",
        "path": "/interest-generation-runs"
      },
      "category": "positive",
      "purpose": "Usar prefixo de dez caracteres sem formato de data e omitir parameterLength.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "categoryBalances": "",
            "crossReferences": "",
            "accounts": "",
            "disclosureGroups": "",
            "transactionOutput": ""
          },
          "parameterDate": "ABCDEFGHIJ"
        }
      },
      "expectedFromContract": {
        "transport": "parameterDate não possui restrição de formato de data. Quando parameterLength é omitido, o transporte fornece o comprimento do prefixo.",
        "on200": {
          "required": [
            "generatedTransactions",
            "diagnostics"
          ],
          "obligations": [
            "generatedTransactions é um array de Transaction em ordem de saída sequencial; diagnostics é um array de strings.",
            "Se houver transações geradas, seus IDs usam o prefixo ABCDEFGHIJ seguido do contador de seis dígitos, iniciado em 000001.",
            "Os timestamps gerados usam CURRENT-DATE, não parameterDate.",
            "Conclusão não implica atualização da última conta nem postagem ou merge das transações geradas."
          ]
        },
        "on500": "Falhas fatais detectadas são mapeadas para ExecutionFailure; saídas e reescritas anteriores podem persistir, e a entrega HTTP depende do ambiente."
      },
      "limitations": [
        "Bindings vazios não estabelecem existência, organização ou conteúdo dos arquivos.",
        "Não é possível determinar quantidade de transações, taxas, valores ou contas alteradas.",
        "Nenhuma fixture de saldos ou grupos de divulgação foi criada."
      ]
    },
    {
      "id": "interest-boundary-01",
      "operation": {
        "method": "POST",
        "path": "/interest-generation-runs"
      },
      "category": "boundary",
      "purpose": "Combinar prefixo vazio permitido com o limite inferior de parameterLength.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "categoryBalances": "",
            "crossReferences": "",
            "accounts": "",
            "disclosureGroups": "",
            "transactionOutput": ""
          },
          "parameterDate": "",
          "parameterLength": -9999
        }
      },
      "expectedFromContract": {
        "transport": "O prefixo vazio é permitido e preenchido com espaços até dez caracteres. -9999 é o mínimo permitido de parameterLength, campo não examinado pelo programa.",
        "on200": {
          "required": [
            "generatedTransactions",
            "diagnostics"
          ],
          "obligations": [
            "generatedTransactions contém registros Transaction em ordem sequencial.",
            "Se houver geração, o prefixo dos IDs contém dez espaços e o primeiro sufixo é 000001.",
            "Não há obrigação de que parameterLength corresponda ao comprimento de parameterDate."
          ]
        },
        "on500": "Falhas fatais detectadas usam o schema ExecutionFailure, sem garantia de desfazer efeitos anteriores."
      },
      "limitations": [
        "Representabilidade não garante execução: os bindings são strings vazias sem dataset conhecido.",
        "Este cenário combina dois limites e não isola seus efeitos.",
        "Não é possível forçar saldo vazio, taxa zero ou mudança de conta apenas com esses campos."
      ]
    },
    {
      "id": "interest-negative-01",
      "operation": {
        "method": "POST",
        "path": "/interest-generation-runs"
      },
      "category": "negative",
      "purpose": "Exceder em um caractere a largura máxima de parameterDate.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "categoryBalances": "",
            "crossReferences": "",
            "accounts": "",
            "disclosureGroups": "",
            "transactionOutput": ""
          },
          "parameterDate": "ABCDEFGHIJK"
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligations": [
          "parameterDate possui onze caracteres e viola maxLength: 10."
        ],
        "responseSchema": "A resposta 400 não declara schema de corpo."
      },
      "limitations": [
        "Não se presume truncamento automático de texto maior que a largura declarada.",
        "O contrato não determina mensagem de erro."
      ]
    },
    {
      "id": "interest-negative-02",
      "operation": {
        "method": "POST",
        "path": "/interest-generation-runs"
      },
      "category": "negative",
      "purpose": "Exceder o limite superior de parameterLength, mesmo sendo um campo não examinado pelo programa.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "categoryBalances": "",
            "crossReferences": "",
            "accounts": "",
            "disclosureGroups": "",
            "transactionOutput": ""
          },
          "parameterDate": "",
          "parameterLength": 10000
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligations": [
          "parameterLength viola maximum: 9999.",
          "O fato de o programa não examinar o campo não remove a restrição do transporte."
        ],
        "responseSchema": "A resposta 400 não declara schema de corpo."
      },
      "limitations": [
        "Não são inferidos diagnósticos COBOL ou execução de geração para esse request inválido."
      ]
    },
    {
      "id": "report-positive-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "positive",
      "purpose": "Representar intervalo textual invertido, separador arbitrário e um segundo registro de parâmetros, sem adicionar validação de calendário.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "crossReferences": "",
            "transactionTypes": "",
            "transactionCategories": "",
            "reportOutput": ""
          },
          "transactions": [],
          "dateParameterRecords": [
            "ZZZZZZZZZZ?AAAAAAAAAA",
            "BBBBBBBBBB!CCCCCCCCCC"
          ]
        }
      },
      "expectedFromContract": {
        "transport": "Intervalos invertidos, texto não calendário, separador arbitrário e entrada de transações vazia são representáveis.",
        "on200": {
          "required": [
            "lines",
            "diagnostics"
          ],
          "obligations": [
            "Somente o primeiro registro DATEPARM é lido: início ZZZZZZZZZZ e fim AAAAAAAAAA.",
            "O caractere na posição 11 não é validado; o segundo registro é ignorado.",
            "lines é um array ordenado de strings com exatamente 133 caracteres cada, sem delimitadores de nova linha do transporte.",
            "diagnostics é um array de strings."
          ]
        },
        "on500": "Falhas fatais detectadas usam ExecutionFailure; saída parcial pode persistir e a entrega HTTP depende do ambiente."
      },
      "limitations": [
        "Bindings vazios não garantem arquivos acessíveis.",
        "Entrada vazia e conteúdo do buffer após READ sem sucesso são sensíveis ao runtime; não se fixa quantidade de linhas nem totais.",
        "Sem transações, este candidato não demonstra a filtragem de registros concretos."
      ]
    },
    {
      "id": "report-boundary-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "boundary",
      "purpose": "Representar EOF imediato de DATEPARM e arquivo de transações vazio.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "crossReferences": "",
            "transactionTypes": "",
            "transactionCategories": "",
            "reportOutput": ""
          },
          "transactions": [],
          "dateParameterRecords": []
        }
      },
      "expectedFromContract": {
        "transport": "Ambos os arrays vazios satisfazem o schema.",
        "on200": {
          "required": [
            "lines",
            "diagnostics"
          ],
          "obligations": [
            "DATEPARM vazio sinaliza EOF e o processamento das transações é pulado.",
            "Cada elemento eventualmente presente em lines deve ter exatamente 133 caracteres.",
            "diagnostics deve ser um array de strings."
          ]
        },
        "on500": "Mesmo com entradas vazias, falhas fatais de arquivos podem ser mapeadas para ExecutionFailure."
      },
      "limitations": [
        "Não se confunde ausência de processamento de transações com dispensa das precondições de execução.",
        "Não se fixa saída textual ou quantidade de linhas além das obrigações expressas.",
        "Os identificadores de bindings não afirmam existência de datasets."
      ]
    },
    {
      "id": "report-negative-01",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "negative",
      "purpose": "Fornecer um registro DATEPARM de 81 caracteres, acima da largura declarada.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "crossReferences": "",
            "transactionTypes": "",
            "transactionCategories": "",
            "reportOutput": ""
          },
          "transactions": [],
          "dateParameterRecords": [
            "123456789012345678901234567890123456789012345678901234567890123456789012345678901"
          ]
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligations": [
          "O item de dateParameterRecords viola maxLength: 80.",
          "A ausência de validação do conteúdo de posições restantes não remove o limite de largura do registro no transporte."
        ],
        "responseSchema": "A resposta 400 não declara schema de corpo."
      },
      "limitations": [
        "Não se presume truncamento de registros excedentes.",
        "Não há mensagem de erro obrigatória nem resultado de relatório inferível."
      ]
    },
    {
      "id": "report-negative-02",
      "operation": {
        "method": "POST",
        "path": "/transaction-report-runs"
      },
      "category": "negative",
      "purpose": "Omitir dateParameterRecords, distinguindo ausência da propriedade obrigatória de um arquivo DATEPARM vazio.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "bindings": {
            "crossReferences": "",
            "transactionTypes": "",
            "transactionCategories": "",
            "reportOutput": ""
          },
          "transactions": []
        }
      },
      "expectedFromContract": {
        "status": 400,
        "obligations": [
          "dateParameterRecords está em required e não foi fornecido.",
          "O contrato não declara substituição da propriedade ausente por um array vazio."
        ],
        "responseSchema": "A resposta 400 não declara schema de corpo."
      },
      "limitations": [
        "Não há formato obrigatório para o corpo de erro.",
        "Foram gerados quatro candidatos por operação; não há cobertura exaustiva de campos, limites ou ramos dependentes de datasets.",
        "Nenhum candidato foi executado ou validado em servidor."
      ]
    }
  ]
}
